(function(){var r=document.getElementById('shopify-section-results');if(!r)return;var t=r.querySelector('[data-rnr-track]'),p=r.querySelector('[data-rnr-prev]'),n=r.querySelector('[data-rnr-next]'),f=r.querySelector('[data-rnr-fill]');if(!t)return;var raf=0;function step(){var c=t.querySelector('.rnr__card');return c?c.getBoundingClientRect().width+parseFloat(getComputedStyle(t).columnGap||0):t.clientWidth}function upd(){raf=0;var m=t.scrollWidth-t.clientWidth,x=t.scrollLeft;p.disabled=x<=2;n.disabled=x>=m-2;var w=m>0?t.clientWidth/t.scrollWidth:1;f.style.width=(w*100)+'%';f.style.left=(m>0?(x/m)*(1-w)*100:0)+'%'}t.addEventListener('scroll',function(){if(!raf)raf=requestAnimationFrame(upd)},{passive:true});addEventListener('resize',function(){if(!raf)raf=requestAnimationFrame(upd)});var sm=matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';p.addEventListener('click',function(){t.scrollBy({left:-step(),behavior:sm})});n.addEventListener('click',function(){t.scrollBy({left:step(),behavior:sm})});upd()})();